const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  return [{ json: { user_id: payload.sub, tenant_id: payload.tenant_id, role: payload.role || 'architect', project_id: projectId, request_id: 'req_' + Math.random().toString(36).slice(2, 10) }}];
} catch (e) { return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message }}]; }

const sess = $('Decode JWT + Body').first().json;
const projectRows = $('Load Project').all().map(i => i.json).filter(p => p && p.id);
const designRows = $('Load Design').all().map(i => i.json).filter(d => d && d.id);
const costRows = $input.all().map(i => i.json).filter(c => c && c.id);

if (projectRows.length === 0) return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe', request_id: sess.request_id }}];
if (designRows.length === 0) return [{ json: { _error: 'DESIGN_NOT_SELECTED', _status: 422, _details: 'No hay design_option seleccionada', request_id: sess.request_id }}];

const project = projectRows[0];
const design = designRows[0];
const cost = costRows[0] || null;

const systemPrompt = `Eres agent_trades, jefe de obra que prepara las solicitudes de presupuesto a gremios.

ESPECIALIDADES VALIDAS (trade_type): albanileria, fontaneria, electricidad, carpinteria, climatizacion, pintura, ceramica, otros.

REGLAS:
- Genera UNA trade_request por especialidad NECESARIA segun el design + costes.
- Cada request con: trade_type, description (que tiene que hacer), expected_budget_eur (del breakdown del cost_estimate), quantity_units (m2, ud, ml, etc.), urgency (low/medium/high segun urgency del proyecto y dependencias).
- Si una especialidad no aplica al design, NO la incluyas.
- Orden recomendado por dependencias (albanileria primero, pintura ultimo).
- DEVUELVE SOLO JSON valido.`;

const userPrompt = `PROYECTO: ${project.name} (${project.project_type}, ${project.property_area_m2 ?? '?'} m2, urgencia ${project.urgency})
Ubicacion: ${project.location_city}, ${project.location_province}

DESIGN: ${design.title}
Logica: ${(design.intervention_logic || '').slice(0, 600)}
Rooms layout: ${JSON.stringify(design.rooms_layout ?? [])}

COST ESTIMATE${cost ? ' (v' + cost.version + ', total ' + cost.total_estimated + ' EUR)' : ' (no disponible)'}:
${cost ? JSON.stringify(cost.breakdown ?? [], null, 2).slice(0, 1500) : 'sin breakdown'}

TAREA:
Genera lista de trade_requests, una por cada especialidad necesaria.

OUTPUT JSON:
{
  "trade_requests": [
    { "trade_type": "albanileria", "description": "Demolicion + albanileria humeda 35 m2", "expected_budget_eur": 4500, "quantity_units": { "m2": 35 }, "urgency": "high", "dependencies": [], "order": 1 }
  ],
  "orden_recomendado": ["albanileria", "..."],
  "notes": "..."
}`;

return [{ json: { user_id: sess.user_id, tenant_id: sess.tenant_id, project_id: project.id, request_id: sess.request_id, design_id: design.id, cost_estimate_id: cost ? cost.id : null, llm_payload: { model: 'gpt-4o', messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }], temperature: 0.2, max_tokens: 2000, response_format: { type: 'json_object' }}}}];

const llm = $input.first()?.json;
const built = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message, _raw: raw.slice(0, 500), request_id: built.request_id }}];
}
const usage = llm?.usage || {};
const trades = Array.isArray(parsed.trade_requests) ? parsed.trade_requests : [];
// Validar trade_type
const validTypes = ['albanileria','fontaneria','electricidad','carpinteria','climatizacion','pintura','ceramica','otros'];
const filtered = trades.filter(t => validTypes.includes((t.trade_type || '').toLowerCase()));
return [{ json: { user_id: built.user_id, tenant_id: built.tenant_id, project_id: built.project_id, request_id: built.request_id, trade_count: filtered.length, output: { trade_requests: filtered, orden_recomendado: parsed.orden_recomendado || [], notes: parsed.notes || null }, model: llm?.model || 'gpt-4o', tokens_in: usage.prompt_tokens || 0, tokens_out: usage.completion_tokens || 0 }}];
